const input = $input.first().json;
const rawText   = input.body?.data?.message?.conversation || input.message || '';
const messageType = input.body?.data?.messageType || 'conversation';
const jid       = input.remotejid || input.body?.data?.key?.remoteJid || 'unknown';

// Sessão vem do Postgres via buscar_sessao_ativa_pg
const sessionActive      = input._pg_session_ativa === true;
const welcomeAlreadySent = input._pg_welcome_sent  === true;

if (sessionActive) {
  const textoLower = rawText.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const horaAliases = ['meio dia','meio-dia','as 5','17h','16h','15h','14h','13h','12h','11h','10h','9h','18h','19h'];
  const eHoraIsolada = horaAliases.some(h => textoLower.includes(h)) ||
    /^\s*(as?\s+)?\d{1,2}(:\d{2})?\s*(h|hs|horas?|por favor|pf|pfv)?\s*[!?.]*\s*$/.test(textoLower);
  return [{ json: { ...input, jid, textOriginal: rawText, message: rawText,
    text: rawText.toLowerCase().trim(), messageType, intent: 'schedule',
    isGreeting: false, agent: 'MAIN_AGENT', shouldSendWelcome: true,
    welcomeAlreadySent, _sessionActive: true, _eHoraIsolada: eHoraIsolada } }];
}

const normalize = t =>
  t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')
   .replace(/[^\w\s]/g,' ').replace(/\s+/g,' ').trim();
const text   = normalize(rawText);
const tokens = text.split(' ');

if (!text || messageType !== 'conversation') {
  return [{ json: { ...input, jid, textOriginal: rawText, message: rawText, text,
    intent: 'unknown', isGreeting: false, agent: 'MAIN_AGENT',
    shouldSendWelcome: false, welcomeAlreadySent: true } }];
}

const patterns = [
  { intent: 'cancel',   regexes: [/nao (vou|consigo|posso) (ir|comparecer|aparecer)/,/tive (um |)imprevisto/,/(cancelar|desmarcar|excluir)/,/nao vai (rolar|dar)/] },
  { intent: 'update',   regexes: [/(reagendar|remarcar)/,/(mudar|alterar|trocar) (o |)(horario|dia|data)/,/outro (horario|dia)/] },
  { intent: 'schedule', regexes: [/(quero|gostaria|preciso|tem como) (marcar|agendar)/,/(marcar|agendar) (um |)(horario|agendamento)/,
    /tapa no visual/,/(corte|barba|sobrancelha).{0,30}(marcar|agendar)/,
    /(segunda|terca|quarta|quinta|sexta|sabado|hoje|amanha).{0,20}(\d{1,2}h|\d{1,2}:\d{2})/] },
  { intent: 'hours',    regexes: [/horario de funcionamento/,/ate que horas/,/(abre|fecha).{0,10}(sabado|hoje)/] },
  { intent: 'price',    regexes: [/quanto (custa|sai|fica)/,/(preco|valor)/] },
  { intent: 'payment',  regexes: [/aceita(m)? (pix|cartao)/,/forma(s)? de pagamento/] },
  { intent: 'location', regexes: [/onde (fica|voces ficam)/,/o endereco/] },
  { intent: 'human',    regexes: [/falar com (um |)(humano|atendente)/] },
  { intent: 'welcome',  regexes: [/^(oi|ola|oie|opa|eai|salve|fala|bom dia|boa tarde|boa noite)(\s|$)/] },
];

let detectedIntent = 'unknown';
for (const { intent, regexes } of patterns) {
  for (const re of regexes) { if (re.test(text)) { detectedIntent = intent; break; } }
  if (detectedIntent !== 'unknown') break;
}
if (detectedIntent === 'unknown') {
  const temDia = /(segunda|terca|quarta|quinta|sexta|sabado|hoje|amanha)/.test(text);
  const temH   = /(\d{1,2}h|\d{1,2}:\d{2}|manha|tarde|noite)/.test(text);
  const temS   = /(corte|barba|cabelo|fade|visual)/.test(text);
  if ((temDia && temH) || (temS && temDia) || (temS && temH)) detectedIntent = 'schedule';
}
if (detectedIntent === 'welcome' && tokens.length > 6) detectedIntent = 'unknown';

const isGreeting        = detectedIntent === 'welcome';
const isScheduleRelated = ['schedule','cancel','update'].includes(detectedIntent);

return [{ json: { ...input, jid, textOriginal: rawText, message: rawText, text, messageType,
  intent: detectedIntent, isGreeting, agent: 'MAIN_AGENT',
  shouldSendWelcome: !welcomeAlreadySent, welcomeAlreadySent,
  _deve_ativar_sessao: isScheduleRelated } }];

