// ==========================================
// MESSAGE SPLITTER
// Divide mensagens longas em partes menores
// para envio sequencial no WhatsApp
// ==========================================

const MAX_CHARS = 1500; // WhatsApp suporta até ~4096 mas mantemos menor para UX
const SEPARATOR_PATTERNS = [
  /\n\n+/g,      // parágrafos duplos
  /\.\s+/g,      // fim de frase
  /,\s+/g,       // vírgulas
  /\n/g,          // quebras simples
];

const input = $input.first().json;
const rawMessage = input.message || input.output || '';

if (!rawMessage || rawMessage.length <= MAX_CHARS) {
  // Mensagem curta, retorna direto sem split
  return [{
    json: {
      ...input,
      parts: [rawMessage],
      totalParts: 1,
      currentPart: 0,
      isSplit: false
    }
  }];
}

// ==========================================
// Função de split inteligente
// ==========================================
function splitMessage(text, maxLen) {
  if (text.length <= maxLen) return [text];

  const parts = [];
  let remaining = text;

  while (remaining.length > maxLen) {
    let cutAt = maxLen;

    // Tenta cortar em parágrafo duplo
    const dblNewline = remaining.lastIndexOf('\n\n', maxLen);
    if (dblNewline > maxLen * 0.5) {
      cutAt = dblNewline + 2;
    } else {
      // Tenta cortar em quebra de linha
      const newline = remaining.lastIndexOf('\n', maxLen);
      if (newline > maxLen * 0.5) {
        cutAt = newline + 1;
      } else {
        // Tenta cortar em fim de frase
        const period = remaining.lastIndexOf('. ', maxLen);
        if (period > maxLen * 0.5) {
          cutAt = period + 2;
        } else {
          // Tenta cortar em espaço
          const space = remaining.lastIndexOf(' ', maxLen);
          if (space > maxLen * 0.3) {
            cutAt = space + 1;
          }
          // Caso extremo: corta no limite
        }
      }
    }

    const part = remaining.slice(0, cutAt).trim();
    if (part) parts.push(part);
    remaining = remaining.slice(cutAt).trim();
  }

  if (remaining.trim()) {
    parts.push(remaining.trim());
  }

  return parts;
}

const parts = splitMessage(rawMessage, MAX_CHARS);

// Retorna um item por parte para envio sequencial
return parts.map((part, index) => ({
  json: {
    ...input,
    message: part,
    parts,
    totalParts: parts.length,
    currentPart: index,
    isSplit: parts.length > 1
  }
}));

