  if (matchHora) {
    let h = parseInt(matchHora[1]);
    const min = matchHora[2] ? matchHora[2] : '00';
    const periodo = (matchHora[4] || '').toLowerCase();
    if ((periodo.includes('tarde') || periodo.includes('noite') || periodo === 'pm') && h < 12) h += 12;
