if (parcialServico) dados.push('servico: ' + parcialServico);
if (parcialData)    dados.push('data_agendamento: ' + parcialData);
if (parcialHora)    dados.push('hora_agendamento: ' + parcialHora);
let bloco = dados.length > 0
  ? '\n--- DADOS JÁ CONFIRMADOS ---\n' + dados.join('\n') + '\n--- NÃO PERGUNTE NOVAMENTE ---\n'
  : '';
let novoCtx = contextAnterior;
if (respostaAgente.trim()) novoCtx = contextAnterior ? contextAnterior + '\nAtendente: ' + respostaAgente : 'Atendente: ' + respostaAgente;
if (bloco) novoCtx = bloco + (novoCtx ? '\n' + novoCtx : '');
return [{ json: { ...input, jid, pushName, instance, message: respostaAgente, context_text: novoCtx,
  _sessaoAtiva: true, _parcial_nome: parcialNome, _parcial_servico: parcialServico,
  _parcial_data: parcialData, _parcial_hora: parcialHora } }];

// Retry Campos Faltando v8 — sem staticData
const input = $input.first().json;
const jid      = input.jid      || $('Webhook de segurança').first().json?.body?.data?.key?.remoteJid || '';
const pushName = input.pushName || $('Webhook de segurança').first().json?.body?.data?.pushName || '';
const instance = input.instance || $('Webhook de segurança').first().json?.body?.instance || '';
const camposFaltando  = input.campos_faltando || [];
const contextAnterior = input.context_text    || '';
const nomeOk    = (input.nome_cliente     || '').trim();
const servicoOk = (input.servico          || '').trim();
const dataOk    = (input.data_agendamento || '').trim();
const horaOk    = (input.hora_agendamento || '').trim();
const confirmados = [];
if (nomeOk)    confirmados.push('nome_cliente: ' + nomeOk);
if (servicoOk) confirmados.push('servico: ' + servicoOk);
if (dataOk)    confirmados.push('data_agendamento: ' + dataOk);
if (horaOk)    confirmados.push('hora_agendamento: ' + horaOk);
const labels = { nome_cliente: 'nome completo', data_agendamento: 'data (DD/MM/AAAA)', hora_agendamento: 'horário (HH:MM)' };
const listaFaltando = camposFaltando.map(c => labels[c] || c).join(', ');
const instrucao = '\n--- CAMPOS AINDA FALTANDO ---\n'
  + (confirmados.length > 0 ? 'Já confirmados: ' + confirmados.join(' | ') + '\n' : '')
  + 'Ainda precisa: ' + listaFaltando + '\n--- FIM ---\n';
const novoCtx = instrucao + (contextAnterior ? '\n' + contextAnterior : '');
const nomeCliente = nomeOk || pushName || 'você';
let msg = camposFaltando.length === 1
  ? ({ nome_cliente: 'Só faltou seu nome pra confirmar! 😊',
       data_agendamento: `Quase lá, ${nomeCliente}! Qual dia você quer vir?`,
       hora_agendamento: `Boa, ${nomeCliente}! Qual horário te cai melhor?` }[camposFaltando[0]] || `Faltou: ${listaFaltando}`)
  : `Quase lá, ${nomeCliente}! Ainda preciso de: ${listaFaltando}. Pode me passar?`;
return [{ json: { ...input, jid, pushName, instance, message: msg, context_text: novoCtx, _sessaoAtiva: true } }];

